// SimLineupsStart queues an async SIM lineups job (Prefer: respond-async) and returns the 202 job handle.
func (s *DFSSlatesService) SimLineupsStart(ctx context.Context, slateID int64, body *SimLineupsRequest) (*SimJobStatusResponse, error) {
	reqCopy := SimLineupsRequest{}
	if body != nil {
		reqCopy = *body
	}
	res, err := s.client.doRaw(
		ctx,
		"POST",
		dfsSlateSubpath(slateID, "/sim/lineups"),
		&reqCopy,
		map[string]string{"Prefer": "respond-async"},
		false,
	)
	if err != nil {
		return nil, err
	}
	var statusBody SimJobStatusResponse
	if err := json.Unmarshal(res.body, &statusBody); err != nil {
		return nil, fmt.Errorf("stat-api: decode SimJobStatusResponse: %w", err)
	}
	return &statusBody, nil
}

// SimJob polls a queued SIM job once via GET /dfs/slates/{slate_id}/sim/jobs/{job_id}.
func (s *DFSSlatesService) SimJob(ctx context.Context, slateID int64, jobID string) (*SimJobPollResult, error) {
	path := dfsSlateSubpath(slateID, "/sim/jobs/"+url.PathEscape(jobID))
	res, err := s.client.doRaw(
		ctx,
		"GET",
		path,
		nil,
		map[string]string{"Accept": "application/json, text/csv;q=0.9"},
		true,
	)
	if err != nil {
		return nil, err
	}
	if res.status == 202 {
		var st SimJobStatusResponse
		if err := json.Unmarshal(res.body, &st); err != nil {
			return nil, err
		}
		return &SimJobPollResult{Ready: false, Status: &st}, nil
	}
	if strings.Contains(res.header.Get("Content-Type"), "text/csv") {
		csvStr := string(res.body)
		return &SimJobPollResult{Ready: true, CSV: &csvStr}, nil
	}
	var out SimLineupsResponse
	if err := json.Unmarshal(res.body, &out); err != nil {
		return nil, err
	}
	return &SimJobPollResult{Ready: true, Result: &out}, nil
}

